kind thread from base
  letter N
  form to: Agent, typed: [Agent], names: [Agent], text: Text, addressed: Named | Unnamed | Sent(by: Agent), follows: Ticket?
  result Kept | Moved(to: Ticket) | OneOff | Between
  pattern
    match addressed {
      Sent(by) => return Between
      _ =>
        v <- match addressed {
          Named => return Thread
          _ => step watcher intake(text, to)
        };
        match v {
          Place(t) =>
            _ <- post text on t as owner naming typed;
            return Moved(t)
          Thread =>
            _ <- post text as owner naming to, names;
            ...
          Unsure(ts) =>
            w <- step owner pick(text, ts);
            match w {
              Place(t) =>
                _ <- post text on t as owner naming typed;
                return Moved(t)
              Thread =>
                _ <- post text as owner naming to, names;
                ...
            }
        }
    }
  when agent_post(p) where p.owner_on do
    q <- step watcher asks(p.text, p.by);
    match q {
      Nothing => return none
      Asks(marks) => mark p marks
    }

program:
r <- match p.answers {
  none =>
    match p.names {
      [] =>
        match (p.naming, p.others) {
          (_, []) =>
            return To(p.naming)
          ([], [a]) =>
            return To([a])
          _ =>
            step watcher route(p.text, p.naming, p.others)
        }
      _ =>
        return To(p.naming)
    }
  _ =>
    return To(p.naming)
};
match r {
  To(as) =>
    tell as p
  Unclear(why) =>
    w <- step owner clarify(p.text, why, p.agents);
    match w {
      Send(as) =>
        tell as p
      Drop =>
        drop p
      Again(t) =>
        _ <- drop p;
        post t on this as owner naming p.naming
    }
}

q <- step watcher asks(p.text, p.by);
match q {
  Nothing =>
    return none
  Asks(marks) =>
    mark p marks
}

try {
  k <- step role minder shape(this);
  continue k
} handle {
  NoWorker(w) =>
    ...
}

